import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.visible .entry matmul_kernel(
    .param .u64 matmul_kernel_param_0,
    .param .u64 matmul_kernel_param_1,
    .param .u64 matmul_kernel_param_2,
    .param .u32 matmul_kernel_param_3,
    .param .u32 matmul_kernel_param_4,
    .param .u32 matmul_kernel_param_5,
    .param .u32 matmul_kernel_param_6
)
{
    .reg .pred %p1, %p2, %p3, %pfull, %pA4, %pB4, %pr<8>, %pc<8>;
    .reg .b32 %tx, %ty, %lid, %bx, %by, %bz;
    .reg .b32 %M, %N, %K, %CHUNK, %kk, %kend, %k2, %tmp;
    .reg .b32 %ml, %kc, %kl, %nc, %grow, %gcol, %akb, %brow, %row, %col;
    .reg .b64 %gA, %gB, %gC, %addr, %w, %w2, %w3, %cstep;
    .reg .b64 %rdAsub, %rdBsub, %rdSA, %rdSB, %rdGA, %rdGB, %rdAp, %rdBp, %rdT;
    .reg .f32 %acc<64>, %va<8>, %vb<8>, %v0, %v1, %v2, %v3;
    .shared .align 16 .f32 smA[2560];
    .shared .align 16 .f32 smB[2048];
    ld.param.u64 %gA, [matmul_kernel_param_0];
    ld.param.u64 %gB, [matmul_kernel_param_1];
    ld.param.u64 %gC, [matmul_kernel_param_2];
    ld.param.u32 %M,  [matmul_kernel_param_3];
    ld.param.u32 %N,  [matmul_kernel_param_4];
    ld.param.u32 %K,  [matmul_kernel_param_5];
    ld.param.u32 %CHUNK, [matmul_kernel_param_6];
    mov.u32 %tx, %tid.x;
    mov.u32 %ty, %tid.y;
    mov.u32 %bx, %ctaid.x;
    mov.u32 %by, %ctaid.y;
    mov.u32 %bz, %ctaid.z;
    mov.u64 %rdAsub, smA;
    mov.u64 %rdBsub, smB;
    // lid = ty*16 + tx
    shl.b32 %lid, %ty, 4;
    add.u32 %lid, %lid, %tx;
    // A tile fragments: rows ml and ml+64, cols kc..kc+3
    shr.u32 %ml, %lid, 2;
    and.b32 %kc, %lid, 3;
    shl.b32 %kc, %kc, 2;
    // B tile fragments: rows kl and kl+8, cols nc..nc+3
    shr.u32 %kl, %lid, 5;
    and.b32 %nc, %lid, 31;
    shl.b32 %nc, %nc, 2;
    // rdSA = &smA[ml*20 + kc]  (128x16 tile, stride 20 padded)
    mul.lo.u32 %tmp, %ml, 20;
    add.u32 %tmp, %tmp, %kc;
    shl.b32 %tmp, %tmp, 2;
    cvt.u64.u32 %w, %tmp;
    add.u64 %rdSA, %rdAsub, %w;
    // rdSB = &smB[kl*128 + nc]  (16x128 tile)
    shl.b32 %tmp, %kl, 7;
    add.u32 %tmp, %tmp, %nc;
    shl.b32 %tmp, %tmp, 2;
    cvt.u64.u32 %w, %tmp;
    add.u64 %rdSB, %rdBsub, %w;
    // Split-K range for this block: [kk, kend)
    mul.lo.u32 %kk, %bz, %CHUNK;
    add.u32 %kend, %kk, %CHUNK;
    min.u32 %kend, %kend, %K;
    // grow = by*128 + ml ; gcol = bx*128 + nc
    shl.b32 %grow, %by, 7;
    add.u32 %grow, %grow, %ml;
    shl.b32 %gcol, %bx, 7;
    add.u32 %gcol, %gcol, %nc;
    // constant byte offsets / strides
    cvt.u64.u32 %w2, %K;
    shl.b64 %w2, %w2, 8;
    cvt.u64.u32 %w3, %N;
    shl.b64 %w3, %w3, 5;
    cvt.u64.u32 %cstep, %N;
    shl.b64 %cstep, %cstep, 6;
    // v4 fast path legal only if K and N are multiples of 4
    and.b32 %tmp, %K, 3;
    setp.eq.u32 %pA4, %tmp, 0;
    and.b32 %tmp, %N, 3;
    setp.eq.u32 %pB4, %tmp, 0;
    // rdGA = gA + (grow*K + kk + kc)*4
    mul.wide.u32 %rdGA, %grow, %K;
    add.u32 %akb, %kk, %kc;
    cvt.u64.u32 %w, %akb;
    add.u64 %rdGA, %rdGA, %w;
    shl.b64 %rdGA, %rdGA, 2;
    add.u64 %rdGA, %rdGA, %gA;
    // rdGB = gB + ((kk+kl)*N + gcol)*4
    add.u32 %brow, %kk, %kl;
    mul.wide.u32 %rdGB, %brow, %N;
    cvt.u64.u32 %w, %gcol;
    add.u64 %rdGB, %rdGB, %w;
    shl.b64 %rdGB, %rdGB, 2;
    add.u64 %rdGB, %rdGB, %gB;
    // zero the 8x8 register accumulators
    mov.f32 %acc0, 0f00000000;
    mov.f32 %acc1, 0f00000000;
    mov.f32 %acc2, 0f00000000;
    mov.f32 %acc3, 0f00000000;
    mov.f32 %acc4, 0f00000000;
    mov.f32 %acc5, 0f00000000;
    mov.f32 %acc6, 0f00000000;
    mov.f32 %acc7, 0f00000000;
    mov.f32 %acc8, 0f00000000;
    mov.f32 %acc9, 0f00000000;
    mov.f32 %acc10, 0f00000000;
    mov.f32 %acc11, 0f00000000;
    mov.f32 %acc12, 0f00000000;
    mov.f32 %acc13, 0f00000000;
    mov.f32 %acc14, 0f00000000;
    mov.f32 %acc15, 0f00000000;
    mov.f32 %acc16, 0f00000000;
    mov.f32 %acc17, 0f00000000;
    mov.f32 %acc18, 0f00000000;
    mov.f32 %acc19, 0f00000000;
    mov.f32 %acc20, 0f00000000;
    mov.f32 %acc21, 0f00000000;
    mov.f32 %acc22, 0f00000000;
    mov.f32 %acc23, 0f00000000;
    mov.f32 %acc24, 0f00000000;
    mov.f32 %acc25, 0f00000000;
    mov.f32 %acc26, 0f00000000;
    mov.f32 %acc27, 0f00000000;
    mov.f32 %acc28, 0f00000000;
    mov.f32 %acc29, 0f00000000;
    mov.f32 %acc30, 0f00000000;
    mov.f32 %acc31, 0f00000000;
    mov.f32 %acc32, 0f00000000;
    mov.f32 %acc33, 0f00000000;
    mov.f32 %acc34, 0f00000000;
    mov.f32 %acc35, 0f00000000;
    mov.f32 %acc36, 0f00000000;
    mov.f32 %acc37, 0f00000000;
    mov.f32 %acc38, 0f00000000;
    mov.f32 %acc39, 0f00000000;
    mov.f32 %acc40, 0f00000000;
    mov.f32 %acc41, 0f00000000;
    mov.f32 %acc42, 0f00000000;
    mov.f32 %acc43, 0f00000000;
    mov.f32 %acc44, 0f00000000;
    mov.f32 %acc45, 0f00000000;
    mov.f32 %acc46, 0f00000000;
    mov.f32 %acc47, 0f00000000;
    mov.f32 %acc48, 0f00000000;
    mov.f32 %acc49, 0f00000000;
    mov.f32 %acc50, 0f00000000;
    mov.f32 %acc51, 0f00000000;
    mov.f32 %acc52, 0f00000000;
    mov.f32 %acc53, 0f00000000;
    mov.f32 %acc54, 0f00000000;
    mov.f32 %acc55, 0f00000000;
    mov.f32 %acc56, 0f00000000;
    mov.f32 %acc57, 0f00000000;
    mov.f32 %acc58, 0f00000000;
    mov.f32 %acc59, 0f00000000;
    mov.f32 %acc60, 0f00000000;
    mov.f32 %acc61, 0f00000000;
    mov.f32 %acc62, 0f00000000;
    mov.f32 %acc63, 0f00000000;
    // skip loop entirely if this partition has no work (uniform branch)
    setp.lt.u32 %p1, %kk, %kend;
    @!%p1 bra STORE;
LOOP_K:
    // ---------- stage A frag0: rows grow, cols kk+kc .. +3 ----------
    add.u32 %akb, %kk, %kc;
    setp.lt.u32 %p1, %grow, %M;
    add.u32 %tmp, %akb, 3;
    setp.lt.u32 %p2, %tmp, %K;
    and.pred %pfull, %p1, %p2;
    and.pred %pfull, %pfull, %pA4;
    mov.f32 %v0, 0f00000000;
    mov.f32 %v1, 0f00000000;
    mov.f32 %v2, 0f00000000;
    mov.f32 %v3, 0f00000000;
    @!%pfull bra A0_SLOW;
    ld.global.v4.f32 {%v0,%v1,%v2,%v3}, [%rdGA];
    bra A0_ST;
A0_SLOW:
    setp.lt.u32 %p2, %akb, %K;
    and.pred %p2, %p1, %p2;
    @%p2 ld.global.f32 %v0, [%rdGA];
    add.u32 %tmp, %akb, 1;
    setp.lt.u32 %p2, %tmp, %K;
    and.pred %p2, %p1, %p2;
    @%p2 ld.global.f32 %v1, [%rdGA+4];
    add.u32 %tmp, %akb, 2;
    setp.lt.u32 %p2, %tmp, %K;
    and.pred %p2, %p1, %p2;
    @%p2 ld.global.f32 %v2, [%rdGA+8];
    add.u32 %tmp, %akb, 3;
    setp.lt.u32 %p2, %tmp, %K;
    and.pred %p2, %p1, %p2;
    @%p2 ld.global.f32 %v3, [%rdGA+12];
A0_ST:
    st.shared.v4.f32 [%rdSA], {%v0,%v1,%v2,%v3};
    // ---------- stage A frag1: rows grow+64 ----------
    add.u32 %tmp, %grow, 64;
    setp.lt.u32 %p1, %tmp, %M;
    add.u32 %tmp, %akb, 3;
    setp.lt.u32 %p2, %tmp, %K;
    and.pred %pfull, %p1, %p2;
    and.pred %pfull, %pfull, %pA4;
    add.u64 %addr, %rdGA, %w2;
    add.u64 %rdT, %rdSA, 5120;
    mov.f32 %v0, 0f00000000;
    mov.f32 %v1, 0f00000000;
    mov.f32 %v2, 0f00000000;
    mov.f32 %v3, 0f00000000;
    @!%pfull bra A1_SLOW;
    ld.global.v4.f32 {%v0,%v1,%v2,%v3}, [%addr];
    bra A1_ST;
A1_SLOW:
    setp.lt.u32 %p2, %akb, %K;
    and.pred %p2, %p1, %p2;
    @%p2 ld.global.f32 %v0, [%addr];
    add.u32 %tmp, %akb, 1;
    setp.lt.u32 %p2, %tmp, %K;
    and.pred %p2, %p1, %p2;
    @%p2 ld.global.f32 %v1, [%addr+4];
    add.u32 %tmp, %akb, 2;
    setp.lt.u32 %p2, %tmp, %K;
    and.pred %p2, %p1, %p2;
    @%p2 ld.global.f32 %v2, [%addr+8];
    add.u32 %tmp, %akb, 3;
    setp.lt.u32 %p2, %tmp, %K;
    and.pred %p2, %p1, %p2;
    @%p2 ld.global.f32 %v3, [%addr+12];
A1_ST:
    st.shared.v4.f32 [%rdT], {%v0,%v1,%v2,%v3};
    // ---------- stage B frag0: rows kk+kl, cols gcol .. +3 ----------
    add.u32 %brow, %kk, %kl;
    setp.lt.u32 %p1, %brow, %K;
    add.u32 %tmp, %gcol, 3;
    setp.lt.u32 %p2, %tmp, %N;
    and.pred %pfull, %p1, %p2;
    and.pred %pfull, %pfull, %pB4;
    mov.f32 %v0, 0f00000000;
    mov.f32 %v1, 0f00000000;
    mov.f32 %v2, 0f00000000;
    mov.f32 %v3, 0f00000000;
    @!%pfull bra B0_SLOW;
    ld.global.v4.f32 {%v0,%v1,%v2,%v3}, [%rdGB];
    bra B0_ST;
B0_SLOW:
    setp.lt.u32 %p2, %gcol, %N;
    and.pred %p2, %p1, %p2;
    @%p2 ld.global.f32 %v0, [%rdGB];
    add.u32 %tmp, %gcol, 1;
    setp.lt.u32 %p2, %tmp, %N;
    and.pred %p2, %p1, %p2;
    @%p2 ld.global.f32 %v1, [%rdGB+4];
    add.u32 %tmp, %gcol, 2;
    setp.lt.u32 %p2, %tmp, %N;
    and.pred %p2, %p1, %p2;
    @%p2 ld.global.f32 %v2, [%rdGB+8];
    add.u32 %tmp, %gcol, 3;
    setp.lt.u32 %p2, %tmp, %N;
    and.pred %p2, %p1, %p2;
    @%p2 ld.global.f32 %v3, [%rdGB+12];
B0_ST:
    st.shared.v4.f32 [%rdSB], {%v0,%v1,%v2,%v3};
    // ---------- stage B frag1: rows kk+kl+8 ----------
    add.u32 %tmp, %brow, 8;
    setp.lt.u32 %p1, %tmp, %K;
    add.u32 %tmp, %gcol, 3;
    setp.lt.u32 %p2, %tmp, %N;
    and.pred %pfull, %p1, %p2;
    and.pred %pfull, %pfull, %pB4;
    add.u64 %addr, %rdGB, %w3;
    add.u64 %rdT, %rdSB, 4096;
    mov.f32 %v0, 0f00000000;
    mov.f32 %v1, 0f00000000;
    mov.f32 %v2, 0f00000000;
    mov.f32 %v3, 0f00000000;
    @!%pfull bra B1_SLOW;
    ld.global.v4.f32 {%v0,%v1,%v2,%v3}, [%addr];
    bra B1_ST;
B1_SLOW:
    setp.lt.u32 %p2, %gcol, %N;
    and.pred %p2, %p1, %p2;
    @%p2 ld.global.f32 %v0, [%addr];
    add.u32 %tmp, %gcol, 1;
    setp.lt.u32 %p2, %tmp, %N;
    and.pred %p2, %p1, %p2;
    @%p2 ld.global.f32 %v1, [%addr+4];
    add.u32 %tmp, %gcol, 2;
    setp.lt.u32 %p2, %tmp, %N;
    and.pred %p2, %p1, %p2;
    @%p2 ld.global.f32 %v2, [%addr+8];
    add.u32 %tmp, %gcol, 3;
    setp.lt.u32 %p2, %tmp, %N;
    and.pred %p2, %p1, %p2;
    @%p2 ld.global.f32 %v3, [%addr+12];
B1_ST:
    st.shared.v4.f32 [%rdT], {%v0,%v1,%v2,%v3};
    bar.sync 0;
    // rdAp = &smA[ty*20], rdBp = &smB[tx]
    mul.lo.u32 %tmp, %ty, 80;
    cvt.u64.u32 %w, %tmp;
    add.u64 %rdAp, %rdAsub, %w;
    shl.b32 %tmp, %tx, 2;
    cvt.u64.u32 %w, %tmp;
    add.u64 %rdBp, %rdBsub, %w;
    mov.u32 %k2, 0;
K2_LOOP:
    ld.shared.f32 %va0, [%rdAp+0];
    ld.shared.f32 %va1, [%rdAp+1280];
    ld.shared.f32 %va2, [%rdAp+2560];
    ld.shared.f32 %va3, [%rdAp+3840];
    ld.shared.f32 %va4, [%rdAp+5120];
    ld.shared.f32 %va5, [%rdAp+6400];
    ld.shared.f32 %va6, [%rdAp+7680];
    ld.shared.f32 %va7, [%rdAp+8960];
    ld.shared.f32 %vb0, [%rdBp+0];
    ld.shared.f32 %vb1, [%rdBp+64];
    ld.shared.f32 %vb2, [%rdBp+128];
    ld.shared.f32 %vb3, [%rdBp+192];
    ld.shared.f32 %vb4, [%rdBp+256];
    ld.shared.f32 %vb5, [%rdBp+320];
    ld.shared.f32 %vb6, [%rdBp+384];
    ld.shared.f32 %vb7, [%rdBp+448];
    fma.rn.f32 %acc0, %va0, %vb0, %acc0;
    fma.rn.f32 %acc1, %va0, %vb1, %acc1;
    fma.rn.f32 %acc2, %va0, %vb2, %acc2;
    fma.rn.f32 %acc3, %va0, %vb3, %acc3;
    fma.rn.f32 %acc4, %va0, %vb4, %acc4;
    fma.rn.f32 %acc5, %va0, %vb5, %acc5;
    fma.rn.f32 %acc6, %va0, %vb6, %acc6;
    fma.rn.f32 %acc7, %va0, %vb7, %acc7;
    fma.rn.f32 %acc8, %va1, %vb0, %acc8;
    fma.rn.f32 %acc9, %va1, %vb1, %acc9;
    fma.rn.f32 %acc10, %va1, %vb2, %acc10;
    fma.rn.f32 %acc11, %va1, %vb3, %acc11;
    fma.rn.f32 %acc12, %va1, %vb4, %acc12;
    fma.rn.f32 %acc13, %va1, %vb5, %acc13;
    fma.rn.f32 %acc14, %va1, %vb6, %acc14;
    fma.rn.f32 %acc15, %va1, %vb7, %acc15;
    fma.rn.f32 %acc16, %va2, %vb0, %acc16;
    fma.rn.f32 %acc17, %va2, %vb1, %acc17;
    fma.rn.f32 %acc18, %va2, %vb2, %acc18;
    fma.rn.f32 %acc19, %va2, %vb3, %acc19;
    fma.rn.f32 %acc20, %va2, %vb4, %acc20;
    fma.rn.f32 %acc21, %va2, %vb5, %acc21;
    fma.rn.f32 %acc22, %va2, %vb6, %acc22;
    fma.rn.f32 %acc23, %va2, %vb7, %acc23;
    fma.rn.f32 %acc24, %va3, %vb0, %acc24;
    fma.rn.f32 %acc25, %va3, %vb1, %acc25;
    fma.rn.f32 %acc26, %va3, %vb2, %acc26;
    fma.rn.f32 %acc27, %va3, %vb3, %acc27;
    fma.rn.f32 %acc28, %va3, %vb4, %acc28;
    fma.rn.f32 %acc29, %va3, %vb5, %acc29;
    fma.rn.f32 %acc30, %va3, %vb6, %acc30;
    fma.rn.f32 %acc31, %va3, %vb7, %acc31;
    fma.rn.f32 %acc32, %va4, %vb0, %acc32;
    fma.rn.f32 %acc33, %va4, %vb1, %acc33;
    fma.rn.f32 %acc34, %va4, %vb2, %acc34;
    fma.rn.f32 %acc35, %va4, %vb3, %acc35;
    fma.rn.f32 %acc36, %va4, %vb4, %acc36;
    fma.rn.f32 %acc37, %va4, %vb5, %acc37;
    fma.rn.f32 %acc38, %va4, %vb6, %acc38;
    fma.rn.f32 %acc39, %va4, %vb7, %acc39;
    fma.rn.f32 %acc40, %va5, %vb0, %acc40;
    fma.rn.f32 %acc41, %va5, %vb1, %acc41;
    fma.rn.f32 %acc42, %va5, %vb2, %acc42;
    fma.rn.f32 %acc43, %va5, %vb3, %acc43;
    fma.rn.f32 %acc44, %va5, %vb4, %acc44;
    fma.rn.f32 %acc45, %va5, %vb5, %acc45;
    fma.rn.f32 %acc46, %va5, %vb6, %acc46;
    fma.rn.f32 %acc47, %va5, %vb7, %acc47;
    fma.rn.f32 %acc48, %va6, %vb0, %acc48;
    fma.rn.f32 %acc49, %va6, %vb1, %acc49;
    fma.rn.f32 %acc50, %va6, %vb2, %acc50;
    fma.rn.f32 %acc51, %va6, %vb3, %acc51;
    fma.rn.f32 %acc52, %va6, %vb4, %acc52;
    fma.rn.f32 %acc53, %va6, %vb5, %acc53;
    fma.rn.f32 %acc54, %va6, %vb6, %acc54;
    fma.rn.f32 %acc55, %va6, %vb7, %acc55;
    fma.rn.f32 %acc56, %va7, %vb0, %acc56;
    fma.rn.f32 %acc57, %va7, %vb1, %acc57;
    fma.rn.f32 %acc58, %va7, %vb2, %acc58;
    fma.rn.f32 %acc59, %va7, %vb3, %acc59;
    fma.rn.f32 %acc60, %va7, %vb4, %acc60;
    fma.rn.f32 %acc61, %va7, %vb5, %acc61;
    fma.rn.f32 %acc62, %va7, %vb6, %acc62;
    fma.rn.f32 %acc63, %va7, %vb7, %acc63;
    add.u64 %rdAp, %rdAp, 4;
    add.u64 %rdBp, %rdBp, 512;
    add.u32 %k2, %k2, 1;
    setp.lt.u32 %p1, %k2, 16;
    @%p1 bra K2_LOOP;
    bar.sync 0;
    add.u32 %kk, %kk, 16;
    add.u64 %rdGA, %rdGA, 64;
    add.u64 %rdGB, %rdGB, %cstep;
    setp.lt.u32 %p1, %kk, %kend;
    @%p1 bra LOOP_K;
STORE:
    // rows r_i = by*128 + ty + 16*i ; cols c_j = bx*128 + tx + 16*j
    shl.b32 %row, %by, 7;
    add.u32 %row, %row, %ty;
    shl.b32 %col, %bx, 7;
    add.u32 %col, %col, %tx;
    setp.lt.u32 %pr0, %row, %M;
    add.u32 %tmp, %row, 16;
    setp.lt.u32 %pr1, %tmp, %M;
    add.u32 %tmp, %row, 32;
    setp.lt.u32 %pr2, %tmp, %M;
    add.u32 %tmp, %row, 48;
    setp.lt.u32 %pr3, %tmp, %M;
    add.u32 %tmp, %row, 64;
    setp.lt.u32 %pr4, %tmp, %M;
    add.u32 %tmp, %row, 80;
    setp.lt.u32 %pr5, %tmp, %M;
    add.u32 %tmp, %row, 96;
    setp.lt.u32 %pr6, %tmp, %M;
    add.u32 %tmp, %row, 112;
    setp.lt.u32 %pr7, %tmp, %M;
    setp.lt.u32 %pc0, %col, %N;
    add.u32 %tmp, %col, 16;
    setp.lt.u32 %pc1, %tmp, %N;
    add.u32 %tmp, %col, 32;
    setp.lt.u32 %pc2, %tmp, %N;
    add.u32 %tmp, %col, 48;
    setp.lt.u32 %pc3, %tmp, %N;
    add.u32 %tmp, %col, 64;
    setp.lt.u32 %pc4, %tmp, %N;
    add.u32 %tmp, %col, 80;
    setp.lt.u32 %pc5, %tmp, %N;
